        while i < len(s) and s[i] == ' ':
            i += 1
        if i >= len(s):
            break

        if s[i] == '(':
            # Find matching closing paren
            depth = 0
            j = i
            while j < len(s):
                if s[j] == '(':
                    depth += 1
                elif s[j] == ')':
                    depth -= 1
                    if depth == 0:
                        break
                j += 1
            args.append(('paren', s[i+1:j]))
            i = j + 1
        elif s[i] == '"':
            # Quoted string
            j = i + 1
            while j < len(s) and s[j] != '"':
                if s[j] == '\\':
                    j += 1
                j += 1
