#!/usr/bin/env python3
"""fblog - A small tool to view json log files."""

import sys
import os
import json
import re
import argparse
from datetime import datetime, timezone

# Try to import tomllib (Python 3.11+) or fall back to tomli
try:
    import tomllib
except ImportError:
    try:
        import tomli as tomllib
    except ImportError:
        tomllib = None

VERSION = "4.17.0"

# ANSI color codes
RESET = "\033[0m"

def bold(s): return f"\033[1m{s}{RESET}"
def red(s): return f"\033[31m{s}{RESET}"
def green(s): return f"\033[32m{s}{RESET}"
def yellow(s): return f"\033[33m{s}{RESET}"
def blue(s): return f"\033[34m{s}{RESET}"
def cyan(s): return f"\033[36m{s}{RESET}"
def bold_red(s): return f"\033[1;31m{s}{RESET}"
def bold_green(s): return f"\033[1;32m{s}{RESET}"
def bold_yellow(s): return f"\033[1;33m{s}{RESET}"
def bold_blue(s): return f"\033[1;34m{s}{RESET}"
def bold_magenta(s): return f"\033[1;35m{s}{RESET}"
def bold_cyan(s): return f"\033[1;36m{s}{RESET}"

def color_rgb_str(r, g, b, s):
    return f"\033[38;2;{r};{g};{b}m{s}{RESET}"

def bold_color_rgb_str(r, g, b, s):
    return f"\033[1m\033[38;2;{r};{g};{b}m{s}{RESET}{RESET}"


# Level color mapping using the 5-char processed level string
def level_style(processed_level):
    """Apply color to processed level string.
    processed_level is the result of uppercase(fixed_size(5, original_level)).
    We trim it, lowercase it and check what color to use.
    """
    trimmed = processed_level.strip().lower()
    if trimmed == "trace":
        return f"\033[1;36m{processed_level}{RESET}"
    elif trimmed == "debug":
        return f"\033[1;34m{processed_level}{RESET}"
    elif trimmed == "info":
        return f"\033[1;32m{processed_level}{RESET}"
    elif trimmed == "warn":
        return f"\033[1;33m{processed_level}{RESET}"
    elif trimmed == "error" or trimmed == "err":
        return f"\033[1;31m{processed_level}{RESET}"
    else:
        return f"\033[1;35m{processed_level}{RESET}"


def fixed_size(n, s):
    """Pad or truncate string to exactly n chars."""
    if len(s) <= n:
        return s.rjust(n)
    else:
        return s[:n]


def min_size(n, s):
    """Pad string to at least n chars (right-justify/left-pad)."""
    if len(s) < n:
        return s.rjust(n)
    return s


def uppercase(s):
    return s.upper()


# ============== Template engine ==============

def parse_template(template_str):
    """Parse a Handlebars-like template into a list of tokens.
    Returns a list of (type, content) pairs.
    type can be: 'text', 'var', 'expr', 'if_start', 'if_end'
    """
    tokens = []
    i = 0
    text_start = 0

    while i < len(template_str):
        if template_str[i:i+2] == '{{':
            # Emit any preceding text
            if i > text_start:
                tokens.append(('text', template_str[text_start:i]))
            # Find closing }}
            end = template_str.find('}}', i+2)
            if end == -1:
                # Unclosed, treat as text
                tokens.append(('text', template_str[i:]))
                i = len(template_str)
                break
            inner = template_str[i+2:end].strip()
            if inner.startswith('#if '):
                tokens.append(('if_start', inner[4:].strip()))
            elif inner == '/if':
                tokens.append(('if_end', None))
            else:
                tokens.append(('expr', inner))
            i = end + 2
            text_start = i
        else:
            i += 1

    if text_start < len(template_str):
        tokens.append(('text', template_str[text_start:]))

    return tokens


def evaluate_expr(expr, context):
    """Evaluate a template expression like 'bold(red fblog_level)' or 'fblog_message'.
    context is a dict of variable names to string values.
    """
    expr = expr.strip()

    # Try as a simple variable reference
    if re.match(r'^[a-zA-Z_][a-zA-Z0-9_]*$', expr):
        return context.get(expr, '')

    # Try as a string literal
    if (expr.startswith('"') and expr.endswith('"')) or \
       (expr.startswith("'") and expr.endswith("'")):
        return expr[1:-1]

    # Try as a number (for helpers like fixed_size, min_size, color_rgb)
    try:
        float(expr)
        return expr
    except ValueError:
        pass

    # Parse as function call: helper_name arg1 arg2 ...
    # Handle nested parentheses
    helper, args = parse_helper_call(expr)
    if helper is None:
        return context.get(expr, '')

    return call_helper(helper, args, context)


def parse_helper_call(expr):
    """Parse 'helper_name arg1 arg2 ...' where args can be nested (...)."""
    expr = expr.strip()

    # Find the helper name (first token)
    m = re.match(r'^([a-zA-Z_][a-zA-Z0-9_]*)(.*)$', expr, re.DOTALL)
    if not m:
        return None, []

    helper = m.group(1)
    rest = m.group(2).strip()

    if not rest:
        # It's a plain variable reference
        return None, []

    # Parse the arguments
    args = parse_args(rest)
    return helper, args


def parse_args(s):
    """Parse space-separated arguments, handling nested parentheses and quoted strings."""
    args = []
    i = 0
    s = s.strip()

    while i < len(s):
        # Skip whitespace
        while i < len(s) and s[i] == ' ':
            i += 1
        if i >= len(s):
            break

        if s[i] == '(':
            # Find matching closing paren
            depth = 0
            j = i
            while j < len(s):
                if s[j] == '(':
                    depth += 1
                elif s[j] == ')':
                    depth -= 1
                    if depth == 0:
                        break
                j += 1
            args.append(('paren', s[i+1:j]))
            i = j + 1
        elif s[i] == '"':
            # Quoted string
            j = i + 1
            while j < len(s) and s[j] != '"':
                if s[j] == '\\':
                    j += 1
                j += 1
            args.append(('string', s[i+1:j]))
            i = j + 1
        elif s[i] == "'":
            j = i + 1
            while j < len(s) and s[j] != "'":
                j += 1
            args.append(('string', s[i+1:j]))
            i = j + 1
        else:
            # Regular token (variable name or number)
            j = i
            while j < len(s) and s[j] not in (' ', ')', '('):
                j += 1
            token = s[i:j]
            if token:
                args.append(('token', token))
            i = j

    return args


def resolve_arg(arg_type, arg_val, context):
    """Resolve an argument to its string value."""
    if arg_type == 'string':
        return arg_val
    elif arg_type == 'paren':
        # This is a nested expression inside ()
        return evaluate_expr(arg_val, context)
    elif arg_type == 'token':
        # Could be a number or variable
        try:
            return arg_val  # Return as-is for numbers
        except:
            return context.get(arg_val, '')
    return ''


def call_helper(helper, args, context):
    """Call a template helper function."""

    if helper == 'bold':
        if not args:
            return ''
        val = resolve_arg(*args[0], context)
        return f"\033[1m{val}{RESET}"

    elif helper == 'cyan':
        if not args:
            return ''
        val = resolve_arg(*args[0], context)
        return f"\033[36m{val}{RESET}"

    elif helper == 'red':
        if not args:
            return ''
        val = resolve_arg(*args[0], context)
        return f"\033[31m{val}{RESET}"

    elif helper == 'green':
        if not args:
            return ''
        val = resolve_arg(*args[0], context)
        return f"\033[32m{val}{RESET}"

    elif helper == 'blue':
        if not args:
            return ''
        val = resolve_arg(*args[0], context)
        return f"\033[34m{val}{RESET}"

    elif helper == 'yellow':
        if not args:
            return ''
        val = resolve_arg(*args[0], context)
        return f"\033[33m{val}{RESET}"

    elif helper == 'color_rgb':
        if len(args) < 4:
            return ''
        r = resolve_arg(*args[0], context)
        g = resolve_arg(*args[1], context)
        b = resolve_arg(*args[2], context)
        val = resolve_arg(*args[3], context)
        return f"\033[38;2;{r};{g};{b}m{val}{RESET}"

    elif helper == 'fixed_size':
        if len(args) < 2:
            return ''
        n_str = resolve_arg(*args[0], context)
        try:
            n = int(n_str)
        except:
            n = 0
        val = resolve_arg(*args[1], context)
        return fixed_size(n, val)

    elif helper == 'min_size':
        if len(args) < 2:
            return ''
        n_str = resolve_arg(*args[0], context)
        try:
            n = int(n_str)
        except:
            n = 0
        val = resolve_arg(*args[1], context)
        return min_size(n, val)

    elif helper == 'uppercase':
        if not args:
            return ''
        val = resolve_arg(*args[0], context)
        return val.upper()

    elif helper == 'level_style':
        if not args:
            return ''
        val = resolve_arg(*args[0], context)
        return level_style(val)

    else:
        raise ValueError(f"Helper not found {helper}")


def render_template(template_str, context):
    """Render a template string with the given context."""
    tokens = parse_template(template_str)
    result = []
    skip_until_end = 0

    i = 0
    while i < len(tokens):
        tok_type, tok_val = tokens[i]

        if tok_type == 'text':
            if skip_until_end == 0:
                result.append(tok_val)
        elif tok_type == 'if_start':
            if skip_until_end > 0:
                skip_until_end += 1
            else:
                val = context.get(tok_val, '')
                if not val:
                    skip_until_end = 1
        elif tok_type == 'if_end':
            if skip_until_end > 0:
                skip_until_end -= 1
        elif tok_type == 'expr':
            if skip_until_end == 0:
                try:
                    val = evaluate_expr(tok_val, context)
                    result.append(val)
                except ValueError as e:
                    raise ValueError(str(e))
        i += 1

    return ''.join(result)


# ============== Timestamp conversion ==============

def parse_timestamp(ts_val):
    """Parse timestamp value to a displayable string.
    The value might be: ISO string, seconds since epoch, or milliseconds since epoch.
    Returns the raw string if it can't be converted.
    """
    if ts_val is None:
        return ''

    ts_str = str(ts_val)

    # Try to parse as a number (unix timestamp)
    # Accept both int and float
    if isinstance(ts_val, (int, float)):
        ts_num = ts_val
        # If > 1e10, assume milliseconds
        if ts_num > 1e10:
            ts_num = ts_num / 1000.0
        try:
            dt = datetime.fromtimestamp(ts_num, tz=timezone.utc)
            return dt.strftime('%Y-%m-%dT%H:%M:%S')
        except:
            return ts_str

    # Try to parse as string representing a number
    try:
        ts_num = float(ts_str)
        if ts_num > 1e10:
            ts_num = ts_num / 1000.0
        try:
            dt = datetime.fromtimestamp(ts_num, tz=timezone.utc)
            return dt.strftime('%Y-%m-%dT%H:%M:%S')
        except:
            return ts_str
    except ValueError:
        pass

    # Return as-is (it's a string timestamp like ISO 8601)
    return ts_str


# ============== Value formatting for substitution ==============

def format_value_for_substitution(val):
    """Format a JSON value for display in substituted message."""
    if isinstance(val, str):
        return f"\033[1;33m{val}{RESET}"
    elif isinstance(val, bool):
        if val:
            return f"\033[1;32mtrue{RESET}"
        else:
            return f"\033[1;31mfalse{RESET}"
    elif val is None:
        return f"\033[1mnull{RESET}"
    elif isinstance(val, (int, float)):
        return f"\033[1;36m{val}{RESET}"
    elif isinstance(val, list):
        return format_array_for_substitution(val)
    elif isinstance(val, dict):
        return format_object_for_substitution(val)
    else:
        return str(val)


def format_array_for_substitution(arr):
    """Format an array for display in substituted message."""
    DIM = "\033[2m"
    parts = [f"{DIM}[{RESET}"]
    for i, item in enumerate(arr):
        if i > 0:
            parts.append(f"{DIM}, {RESET}")
        parts.append(format_value_for_substitution(item))
    parts.append(f"{DIM}]{RESET}")
    return ''.join(parts)


def format_object_for_substitution(obj):
    """Format an object for display in substituted message."""
    DIM = "\033[2m"
    MAGENTA = "\033[35m"
    parts = [f"{DIM}{{{RESET}"]
    first = True
    for k in sorted(obj.keys()):
        if not first:
            parts.append(f"{DIM}, {RESET}")
        first = False
        parts.append(f"{MAGENTA}{k}{RESET}")
        parts.append(f"{DIM}: {RESET}")
        parts.append(format_value_for_substitution(obj[k]))
    parts.append(f"{DIM}}}{RESET}")
    return ''.join(parts)


# ============== Lua filter ==============

class LuaEnvironment:
    """A simplified Lua expression evaluator."""

    def __init__(self, variables):
        self.variables = variables

    def evaluate(self, expr):
        """Evaluate a Lua expression. Returns True/False."""
        # Simple Lua to Python translation
        python_expr = self._lua_to_python(expr)
        try:
            result = eval(python_expr, {'__builtins__': {}}, self._get_py_vars())
            return bool(result)
        except Exception as e:
            raise RuntimeError(f"Error evaluating filter: {e}")

    def _get_py_vars(self):
        """Get Python variables from Lua variables."""
        py_vars = {}
        for k, v in self.variables.items():
            py_vars[k] = v

        # Add string module emulation
        import re as _re

        class StringModule:
            @staticmethod
            def find(s, pattern, init=1, plain=False):
                if s is None:
                    return None
                s = str(s)
                if plain:
                    idx = s.find(pattern, init-1)
                    if idx == -1:
                        return None
                    return (idx+1, idx+len(pattern))
                try:
                    # Convert Lua patterns to Python regex (basic)
                    py_pattern = lua_pattern_to_python(pattern)
                    m = _re.search(py_pattern, s[init-1:])
                    if m:
                        return (m.start() + init, m.end() + init - 1)
                    return None
                except:
                    return None

            @staticmethod
            def match(s, pattern, init=1):
                if s is None:
                    return None
                s = str(s)
                try:
                    py_pattern = lua_pattern_to_python(pattern)
                    m = _re.match(py_pattern, s[init-1:])
                    if m:
                        return m.group(0)
                    return None
                except:
                    return None

            @staticmethod
            def lower(s):
                if s is None:
                    return None
                return str(s).lower()

            @staticmethod
            def upper(s):
                if s is None:
                    return None
                return str(s).upper()

            @staticmethod
            def len(s):
                if s is None:
                    return 0
                return len(str(s))

            @staticmethod
            def sub(s, i, j=None):
                if s is None:
                    return ''
                s = str(s)
                if j is None:
                    return s[i-1:]
                return s[i-1:j]

            @staticmethod
            def format(fmt, *args):
                # Basic Lua string.format
                # Convert Lua format to Python format
                result = fmt
                for arg in args:
                    result = result.replace('%s', str(arg), 1)
                    result = result.replace('%d', str(int(arg)), 1)
                return result

        py_vars['string'] = StringModule()
        py_vars['_nil_check'] = lambda x: x is None
        py_vars['_not_nil'] = lambda x: x is not None

        # Math module
        class MathModule:
            @staticmethod
            def abs(x): return abs(x)
            @staticmethod
            def floor(x): return int(x)
            @staticmethod
            def ceil(x): import math; return math.ceil(x)

        py_vars['math'] = MathModule()

        return py_vars

    def _lua_to_python(self, expr):
        """Convert Lua expression to Python expression."""
        # Add implicit return
        result = expr

        # Replace Lua operators with Python equivalents
        # ~= -> !=
        result = result.replace('~=', '!=')

        # Lua 'and' -> Python 'and', 'or' -> 'or', 'not' -> 'not'
        # These are already the same in Python!

        # Lua 'nil' -> Python 'None'
        result = re.sub(r'\bnil\b', 'None', result)

        # Lua 'true' -> Python 'True'
        result = re.sub(r'\btrue\b', 'True', result)

        # Lua 'false' -> Python 'False'
        result = re.sub(r'\bfalse\b', 'False', result)

        # Handle string concatenation (..)
        result = result.replace('..', '+')

        return result


def lua_pattern_to_python(pattern):
    """Convert a Lua pattern to a Python regex pattern (basic conversion)."""
    # Basic Lua magic characters: ^ $ ( ) % . [ ] * + - ?
    # %d -> \d, %a -> [a-zA-Z], %w -> \w, %s -> \s, etc.
    # . in Lua matches any char (same as Python)
    # * in Lua is greedy (same as Python)
    # - in Lua is non-greedy (like *? in Python)

    result = []
    i = 0
    while i < len(pattern):
        c = pattern[i]
        if c == '%' and i+1 < len(pattern):
            nc = pattern[i+1]
            if nc == 'd': result.append(r'\d')
            elif nc == 'D': result.append(r'\D')
            elif nc == 'a': result.append('[a-zA-Z]')
            elif nc == 'A': result.append('[^a-zA-Z]')
            elif nc == 'w': result.append(r'\w')
            elif nc == 'W': result.append(r'\W')
            elif nc == 's': result.append(r'\s')
            elif nc == 'S': result.append(r'\S')
            elif nc == 'l': result.append('[a-z]')
            elif nc == 'u': result.append('[A-Z]')
            elif nc == 'p': result.append(r'[!-/:-@[-`{-~]')
            elif nc == 'c': result.append(r'[\x00-\x1f\x7f]')
            elif nc in r'\.^$()[]*+-?{}|':
                result.append('\\' + nc)
            else:
                result.append(re.escape(nc))
            i += 2
        elif c == '-':
            # In Lua, - is non-greedy quantifier (like *?)
            result.append('*?')
            i += 1
        elif c in r'\.^$()[]*+?{}|':
            if c == '.':
                result.append('.')
            elif c == '^':
                result.append('^')
            elif c == '$':
                result.append('$')
            elif c == '*':
                result.append('*')
            elif c == '+':
                result.append('+')
            elif c == '?':
                result.append('?')
            else:
                result.append('\\' + c)
            i += 1
        else:
            result.append(re.escape(c))
            i += 1

    return ''.join(result)


def json_to_lua_vars(data, prefix=''):
    """Convert JSON data to Lua variable assignments dict."""
    result = {}

    if isinstance(data, dict):
        for k, v in data.items():
            lua_key = json_key_to_lua(k)
            if prefix:
                full_key = f"{prefix}_{lua_key}"
            else:
                full_key = lua_key

            if isinstance(v, dict):
                sub = json_to_lua_vars(v, full_key)
                result.update(sub)
                # Also set the table value
                result[full_key] = v
            elif isinstance(v, list):
                result[full_key] = lua_list_to_table(v)
            elif isinstance(v, bool):
                result[full_key] = v
            elif v is None:
                result[full_key] = None
            else:
                result[full_key] = v

    return result


def json_key_to_lua(key):
    """Convert a JSON key to a valid Lua variable name."""
    # Replace non-alphanumeric chars (except _) with _
    result = re.sub(r'[^a-zA-Z0-9_]', '_', key)
    # If starts with a digit, prepend _
    if result and result[0].isdigit():
        result = '_' + result
    return result


def lua_list_to_table(lst):
    """Convert a Python list to a Lua-like structure for evaluation."""
    return lst  # Keep as list for Python eval


def format_lua_value(val):
    """Format a value as it would appear in --print-lua output."""
    if isinstance(val, str):
        return f'"{val}"'
    elif isinstance(val, bool):
        return 'true' if val else 'false'
    elif val is None:
        return 'nil'
    elif isinstance(val, (int, float)):
        return str(val)
    elif isinstance(val, list):
        items = ', '.join(format_lua_value(v) for v in val)
        return '{' + items + '}'
    elif isinstance(val, dict):
        items = ', '.join(f"{k} = {format_lua_value(v)}" for k, v in val.items())
        return '{' + items + '}'
    else:
        return str(val)


# ============== Placeholder substitution ==============

def build_placeholder_regex(format_str):
    """Build a regex from a placeholder format string like '{key}' or '#{key}'.
    'key' in the format is the literal word to replace with a capture group.
    """
    # Escape the format string for regex, except for 'key' which becomes a capture group
    escaped = re.escape(format_str)
    # Replace the escaped 'key' with a capture group
    escaped_key = re.escape('key')
    pattern = escaped.replace(escaped_key, r'([^}]+?)')
    return re.compile(pattern)


def substitute_message(message, context, placeholder_format='{key}', context_key='context'):
    """Substitute placeholders in the message with values from context."""
    if context is None:
        return message

    regex = build_placeholder_regex(placeholder_format)

    result = []
    last_end = 0

    for m in regex.finditer(message):
        result.append(message[last_end:m.start()])
        key = m.group(1)

        if isinstance(context, dict):
            if key in context:
                result.append(format_value_for_substitution(context[key]))
            else:
                # Missing key - show as dim{bold_red_key}
                DIM = "\033[2m"
                result.append(f"{DIM}{{{RESET}\033[1;31m{key}{RESET}{DIM}}}{RESET}")
        elif isinstance(context, list):
            try:
                idx = int(key)
                if 0 <= idx < len(context):
                    result.append(format_value_for_substitution(context[idx]))
                else:
                    DIM = "\033[2m"
                    result.append(f"{DIM}{{{RESET}\033[1;31m{key}{RESET}{DIM}}}{RESET}")
            except ValueError:
                DIM = "\033[2m"
                result.append(f"{DIM}{{{RESET}\033[1;31m{key}{RESET}{DIM}}}{RESET}")

        last_end = m.end()

    result.append(message[last_end:])
    return ''.join(result)


# ============== JSON flattening for dump-all ==============

def flatten_json(data, prefix=''):
    """Flatten a JSON object into a list of (path, value) pairs.
    Uses ' > ' as separator for nested objects and '[i]' for arrays.
    """
    result = []

    if isinstance(data, dict):
        for k, v in sorted(data.items()):
            path = f"{prefix} > {k}" if prefix else k
            if isinstance(v, (dict, list)):
                result.extend(flatten_json(v, path))
            elif v is not None:
                result.append((path, v))
    elif isinstance(data, list):
        for i, v in enumerate(data):
            path = f"{prefix}[{i}]"
            if isinstance(v, (dict, list)):
                result.extend(flatten_json(v, path))
            elif v is not None:
                result.append((path, v))
    else:
        if data is not None:
            result.append((prefix, data))

    return result


def format_dump_value(val):
    """Format a value for dump-all display."""
    if isinstance(val, str):
        return val
    elif isinstance(val, bool):
        return 'true' if val else 'false'
    elif val is None:
        return ''
    elif isinstance(val, (int, float)):
        return str(val)
    else:
        return str(val)


# ============== Main processing ==============

DEFAULT_CONFIG = {
    'message_keys': ['short_message', 'msg', 'message'],
    'time_keys': ['timestamp', 'time', '@timestamp'],
    'level_keys': ['level', 'severity', 'log.level', 'loglevel'],
    'dump_all_exclude': [],
    'always_print_fields': [],
    'main_line_format': '{{bold(fixed_size 19 fblog_timestamp)}} {{level_style (uppercase (fixed_size 5 fblog_level))}}:{{#if fblog_prefix}} {{bold(cyan fblog_prefix)}}{{/if}} {{fblog_message}}',
    'additional_value_format': '{{bold (color_rgb 150 150 150 (min_size 25 key))}}: {{value}}',
    'level_map': {},
}


def load_config(config_file=None):
    """Load configuration from file or default locations."""
    config = DEFAULT_CONFIG.copy()
    config['level_map'] = {}

    if tomllib is None:
        return config

    # Try specified config file first
    if config_file:
        try:
            with open(config_file, 'rb') as f:
                user_config = tomllib.load(f)
            config.update(user_config)
            if 'level_map' not in user_config:
                config['level_map'] = {}
            return config
        except Exception as e:
            print(f"Warning: Could not load config file {config_file}: {e}", file=sys.stderr)
            return config

    # Try standard user config locations
    config_dirs = []
    if 'XDG_CONFIG_HOME' in os.environ:
        config_dirs.append(os.path.join(os.environ['XDG_CONFIG_HOME'], 'fblog.toml'))
    if 'HOME' in os.environ:
        config_dirs.append(os.path.join(os.environ['HOME'], '.config', 'fblog.toml'))

    for config_path in config_dirs:
        if os.path.exists(config_path):
            try:
                with open(config_path, 'rb') as f:
                    user_config = tomllib.load(f)
                config.update(user_config)
                if 'level_map' not in user_config:
                    config['level_map'] = {}
                return config
            except Exception as e:
                pass

    return config


def get_nested_value(data, path):
    """Get a value from nested JSON using ' > ' separated path."""
    if not path:
        return None

    parts = [p.strip() for p in path.split(' > ')]
    current = data

    for part in parts:
        if isinstance(current, dict):
            if part in current:
                current = current[part]
            else:
                return None
        else:
            return None

    return current


def find_value_by_keys(data, keys):
    """Find the first value in data matching one of the given keys."""
    for key in keys:
        if key in data:
            return data[key]
    return None


def process_log_entry(data, config, args, filter_expr=None):
    """Process a parsed JSON log entry and return formatted output lines."""
    level_map = config.get('level_map', {})
    message_keys = config.get('message_keys', DEFAULT_CONFIG['message_keys'])
    time_keys = config.get('time_keys', DEFAULT_CONFIG['time_keys'])
    level_keys = config.get('level_keys', DEFAULT_CONFIG['level_keys'])

    # Find the message
    message = find_value_by_keys(data, message_keys)
    if message is not None:
        message = str(message)
    else:
        message = ''

    # Find the timestamp
    time_val = find_value_by_keys(data, time_keys)
    timestamp = parse_timestamp(time_val) if time_val is not None else ''

    # Find the level
    level_val = find_value_by_keys(data, level_keys)
    if level_val is not None:
        level_str = str(level_val)
    else:
        level_str = ''

    # Apply level mapping (keys are strings, case-insensitive)
    level_lower = level_str.lower()
    for map_from, map_to in level_map.items():
        if str(map_from).lower() == level_lower:
            level_str = map_to
            break

    # Extract prefix if requested
    prefix = args.prefix

    # Build template context
    template_context = {
        'fblog_message': message,
        'fblog_timestamp': timestamp,
        'fblog_level': level_str,
        'fblog_prefix': prefix if prefix else '',
    }

    # Add all JSON fields to template context
    for k, v in data.items():
        template_context[k] = str(v) if not isinstance(v, (dict, list)) else json.dumps(v)

    # Apply Lua filter if specified
    if filter_expr is not None:
        lua_vars = build_lua_vars(data)

        if args.print_lua:
            # Print the Lua variable assignments
            for k in sorted(lua_vars.keys()):
                v = lua_vars[k]
                print(f"{k} = {format_lua_value(v)}")

        try:
            lua_env = LuaEnvironment(lua_vars)
            filter_result = lua_env.evaluate(filter_expr)
            if not filter_result:
                return None, []
        except Exception as e:
            return 'filter_error', [str(e)]

    # Apply placeholder substitution if requested
    if getattr(args, 'substitute', False):
        ctx_key = getattr(args, 'context_key', None) or 'context'
        placeholder_fmt = getattr(args, 'placeholder_format', None) or '{key}'
        context_val = data.get(ctx_key)
        if context_val is not None:
            message = substitute_message(message, context_val, placeholder_fmt, ctx_key)
            template_context['fblog_message'] = message

    # Render the main line
    main_fmt = config.get('main_line_format', DEFAULT_CONFIG['main_line_format'])
    try:
        main_line = render_template(main_fmt, template_context)
    except ValueError as e:
        return 'render_error', [str(e)]

    additional_lines = []

    # Print always_print_fields
    always_fields = config.get('always_print_fields', [])
    additional_value_fmt = config.get('additional_value_format', DEFAULT_CONFIG['additional_value_format'])

    for field in always_fields:
        val = data.get(field)
        if val is not None:
            fmt_val = format_dump_value(val)
            add_ctx = {'key': field, 'value': fmt_val}
            try:
                line = render_template(additional_value_fmt, add_ctx)
                additional_lines.append(line)
            except:
                pass

    # Print -a additional values
    additional_values = getattr(args, 'additional_value', []) or []
    for path in additional_values:
        val = get_nested_value(data, path)
        if val is not None:
            fmt_val = format_dump_value(val)
            add_ctx = {'key': path, 'value': fmt_val}
            try:
                line = render_template(additional_value_fmt, add_ctx)
                additional_lines.append(line)
            except:
                pass

    # Print dump-all or excluded values
    dump_all = getattr(args, 'dump_all', False)
    excluded = getattr(args, 'excluded_value', []) or []
    dump_all_exclude = config.get('dump_all_exclude', [])

    if dump_all or excluded:
        # Flatten the JSON
        flat = flatten_json(data)
        for path, val in sorted(flat, key=lambda x: x[0]):
            # Check exclusions
            if path in dump_all_exclude:
                continue
            if path in excluded:
                continue

            fmt_val = format_dump_value(val)
            add_ctx = {'key': path, 'value': fmt_val}
            try:
                line = render_template(additional_value_fmt, add_ctx)
                additional_lines.append(line)
            except:
                pass

    return main_line, additional_lines


def build_lua_vars(data, prefix=''):
    """Build Lua variable assignments from JSON data."""
    result = {}

    if isinstance(data, dict):
        for k, v in data.items():
            lua_key = json_key_to_lua(k)
            if prefix:
                full_key = f"{prefix}_{lua_key}"
            else:
                full_key = lua_key

            if isinstance(v, dict):
                result[full_key] = v  # Keep as dict for table display
                # Also recurse for nested access
                sub = build_lua_vars(v, full_key)
                result.update(sub)
            elif isinstance(v, list):
                result[full_key] = v
            elif isinstance(v, bool):
                result[full_key] = v
            elif v is None:
                result[full_key] = None
            else:
                result[full_key] = v

    return result


def process_line(line, config, args, filter_expr):
    """Process a single log line."""
    line = line.rstrip('\n')

    # Handle prefix mode
    prefix_text = ''
    json_str = line

    if getattr(args, 'with_prefix', False):
        # Find the first '{' and use everything before it as prefix
        brace_idx = line.find('{')
        if brace_idx > 0:
            prefix_text = line[:brace_idx].rstrip()
            # Remove trailing ' | ' or similar
            if prefix_text.endswith(' |'):
                prefix_text = prefix_text[:-2].rstrip()
            elif prefix_text.endswith('|'):
                prefix_text = prefix_text[:-1].rstrip()
            json_str = line[brace_idx:]
        elif brace_idx == -1:
            # No JSON found
            return [f"\033[1;38;2;255;135;22m??? >{RESET} {line}"]

    # Try to parse as JSON
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return [f"\033[1;38;2;255;135;22m??? >{RESET} {line}"]

    # Must be a JSON object (dict)
    if not isinstance(data, dict):
        return [f"\033[1;38;2;255;135;22m??? >{RESET} {line}"]

    # Add prefix to args temporarily
    args_copy = argparse.Namespace(**vars(args))
    args_copy.prefix = prefix_text if prefix_text else ''

    result_type, content = process_log_entry(data, config, args_copy, filter_expr)

    if result_type is None and not content:
        # Filtered out
        return []
    elif result_type == 'filter_error':
        return [f"\033[31mFailed to apply filter expression{RESET}: '{content[0]}'"]
    elif result_type == 'render_error':
        return [f"\033[1;31m??? >{RESET} Failed to process line: Error rendering \"main_line\" line 1, col 1: {content[0]}"]
    else:
        lines = [result_type]  # result_type is the main line
        lines.extend(content)  # content is additional lines
        return lines


def main():
    parser = argparse.ArgumentParser(
        description='json log viewer',
        formatter_class=argparse.RawDescriptionHelpFormatter
    )

    parser.add_argument('input', nargs='?', default='-',
                       help='Sets the input file to use, otherwise assumes stdin [default: -]',
                       metavar='INPUT')
    parser.add_argument('-a', '--additional-value', action='append', metavar='additional-value',
                       dest='additional_value',
                       help='adds additional values')
    parser.add_argument('--config-file', metavar='config-file', dest='config_file',
                       help='configuration file to load')
    parser.add_argument('-m', '--message-key', action='append', metavar='message-key',
                       dest='message_key',
                       help='Adds an additional key to detect the message in the log entry.')
    parser.add_argument('--print-lua', action='store_true', dest='print_lua',
                       help='Prints lua init expressions. Used for fblog debugging.')
    parser.add_argument('-t', '--time-key', action='append', metavar='time-key',
                       dest='time_key',
                       help='Adds an additional key to detect the time in the log entry.')
    parser.add_argument('-l', '--level-key', action='append', metavar='level-key',
                       dest='level_key',
                       help='Adds an additional key to detect the level in the log entry.')
    parser.add_argument('--map-level', action='append', metavar='from=to',
                       dest='map_level',
                       help='Rewrite the log level from one value to another.')
    parser.add_argument('-d', '--dump-all', action='store_true', dest='dump_all',
                       help='dumps all values')
    parser.add_argument('-x', '--excluded-value', action='append', metavar='excluded-value',
                       dest='excluded_value',
                       help='Excludes values (--dump-all is enabled implicitly)')
    parser.add_argument('-p', '--with-prefix', action='store_true', dest='with_prefix',
                       help='consider all text before opening curly brace as prefix')
    parser.add_argument('-f', '--filter', metavar='filter', dest='filter',
                       help='lua expression to filter log entries.')
    parser.add_argument('--no-implicit-filter-return-statement', action='store_true',
                       dest='no_implicit_filter_return',
                       help="if you pass a filter expression 'return' is automatically prepended.")
    parser.add_argument('--main-line-format', metavar='main-line-format',
                       dest='main_line_format',
                       help='Formats the main fblog output.')
    parser.add_argument('--additional-value-format', metavar='additional-value-format',
                       dest='additional_value_format',
                       help='Formats the additional value fblog output.')
    parser.add_argument('-s', '--substitute', action='store_true', dest='substitute',
                       help='Enable substitution of placeholders in the log messages.')
    parser.add_argument('-c', '--context-key', metavar='context-key', dest='context_key',
                       help='Use this key as the source of substitutions for the message.')
    parser.add_argument('-F', '--placeholder-format', metavar='placeholder-format',
                       dest='placeholder_format',
                       help='The format that should be used for substituting values in the message.')
    parser.add_argument('-V', '--version', action='version', version=f'fblog {VERSION}')

    args = parser.parse_args()

    # If there are excluded values, implicitly enable dump-all
    if args.excluded_value:
        args.dump_all = True

    # Load configuration
    config = load_config(args.config_file)

    # Apply command-line overrides to config
    if args.message_key:
        config['message_keys'] = args.message_key + config.get('message_keys', DEFAULT_CONFIG['message_keys'])

    if args.time_key:
        config['time_keys'] = args.time_key + config.get('time_keys', DEFAULT_CONFIG['time_keys'])

    if args.level_key:
        config['level_keys'] = args.level_key + config.get('level_keys', DEFAULT_CONFIG['level_keys'])

    if args.map_level:
        for mapping in args.map_level:
            parts = mapping.split('=', 1)
            if len(parts) == 2:
                config['level_map'][parts[0]] = parts[1]

    if args.main_line_format:
        config['main_line_format'] = args.main_line_format

    if args.additional_value_format:
        config['additional_value_format'] = args.additional_value_format

    # Build filter expression
    filter_expr = None
    if args.filter:
        filter_expr = args.filter
        if not args.no_implicit_filter_return:
            # Validate the filter expression for syntax
            pass

    # Open input
    if args.input == '-':
        input_file = sys.stdin
    else:
        try:
            input_file = open(args.input, 'r', encoding='utf-8', errors='strict')
        except UnicodeDecodeError:
            pass
        except FileNotFoundError:
            print(f"Error: file not found: {args.input}", file=sys.stderr)
            sys.exit(1)

    # Process lines
    if args.input == '-':
        input_stream = sys.stdin
    else:
        try:
            input_stream = open(args.input, 'r', encoding='utf-8', errors='strict')
        except Exception as e:
            print(f"Error: {e}", file=sys.stderr)
            sys.exit(1)

    try:
        while True:
            try:
                line = input_stream.readline()
                if not line:
                    break

                output_lines = process_line(line, config, args, filter_expr)
                for out_line in output_lines:
                    print(out_line)
            except UnicodeDecodeError as e:
                print(f"\033[1;31m??? >{RESET} Could not read line: stream did not contain valid UTF-8")
    except KeyboardInterrupt:
        pass
    finally:
        if args.input != '-':
            input_stream.close()


if __name__ == '__main__':
    main()
