#!/usr/bin/env python3
"""fblog - A small tool to view json log files.

Version: 4.17.0
"""

import sys
import os
import json
import re
import argparse
from datetime import datetime, timezone

# Try to import tomllib (Python 3.11+) or fall back to tomli
try:
    import tomllib
except ImportError:
    try:
        import tomli as tomllib
    except ImportError:
        tomllib = None

VERSION = "4.17.0"

# ANSI reset code
RESET = "\033[0m"
DIM = "\033[2m"


# ============== Template Engine ==============

def evaluate_expr(expr, context):
    """Evaluate a template expression.
    expr can be: variable_name, "string_literal", helper_name args...
    context is a dict mapping variable names to their string values.
    """
    expr = expr.strip()

    # Empty expression
    if not expr:
        return ''

    # String literal
    if expr.startswith('"') and expr.endswith('"') and len(expr) >= 2:
        return expr[1:-1]
    if expr.startswith("'") and expr.endswith("'") and len(expr) >= 2:
        return expr[1:-1]

    # Simple variable name
    if re.match(r'^[a-zA-Z_][a-zA-Z0-9_.]*$', expr):
        return str(context.get(expr, ''))

    # Number literal
    try:
        float(expr)
        return expr
    except ValueError:
        pass

    # Helper call: parse as "helper_name args..."
    # The helper name is everything up to the first space or '('
    helper, args = parse_helper_call(expr)
    if helper is None:
        # Fall back to variable lookup
        return str(context.get(expr, ''))

    return call_helper(helper, args, context)


def parse_helper_call(expr):
    """Parse a helper call expression.
    Returns (helper_name, args) or (None, []) if not a valid helper call.
    """
    expr = expr.strip()

    # Match helper name: starts with letter/underscore, followed by alphanumeric/underscore
    m = re.match(r'^([a-zA-Z_][a-zA-Z0-9_]*)(.*)$', expr, re.DOTALL)
    if not m:
        return None, []

    helper = m.group(1)
    rest = m.group(2).strip()

    if not rest:
        # Just a variable name, not a helper call
        return None, []

    # Parse the rest as arguments
    args = parse_args(rest)
    return helper, args


def parse_args(s):
    """Parse space-separated arguments with support for:
    - Parenthesized nested expressions: (expr)
    - Quoted strings: "str" or 'str'
    - Plain tokens (variable names, numbers)
    """
    args = []
    i = 0
    s = s.strip()

    while i < len(s):
        # Skip whitespace
        while i < len(s) and s[i] == ' ':
            i += 1
        if i >= len(s):
            break

        if s[i] == '(':
            # Find matching closing paren, accounting for nesting
            depth = 0
            j = i
            while j < len(s):
                if s[j] == '(':
                    depth += 1
                elif s[j] == ')':
                    depth -= 1
                    if depth == 0:
                        break
                j += 1
            args.append(('paren', s[i+1:j]))
            i = j + 1
        elif s[i] == '"':
            # Double-quoted string
            j = i + 1
            while j < len(s) and s[j] != '"':
                if s[j] == '\\' and j+1 < len(s):
                    j += 1
                j += 1
            args.append(('string', s[i+1:j]))
            i = j + 1
        elif s[i] == "'":
            # Single-quoted string
            j = i + 1
            while j < len(s) and s[j] != "'":
                j += 1
            args.append(('string', s[i+1:j]))
            i = j + 1
        else:
            # Regular token (variable name, number)
            j = i
            while j < len(s) and s[j] not in (' ', ')', '('):
                j += 1
            token = s[i:j]
            if token:
                args.append(('token', token))
            i = j

    return args


