# ============== Timestamp Conversion ==============

def parse_timestamp(ts_val):
    """Convert a timestamp value to a displayable string.

    Handles:
    - ISO 8601 strings (returned as-is)
    - Unix timestamps in seconds (int/float)
    - Unix timestamps in milliseconds (int/float > 1e10)
    - String representations of numbers
    """
    if ts_val is None:
        return ''

    # Numeric timestamps
    if isinstance(ts_val, (int, float)) and not isinstance(ts_val, bool):
        ts_num = float(ts_val)
        if ts_num > 1e10:
            ts_num /= 1000.0
        try:
            dt = datetime.fromtimestamp(ts_num, tz=timezone.utc)
            return dt.strftime('%Y-%m-%dT%H:%M:%S')
        except (OSError, OverflowError, ValueError):
            return str(ts_val)

    ts_str = str(ts_val)

    # Try to parse as numeric string
    try:
        ts_num = float(ts_str)
        if ts_num > 1e10:
            ts_num /= 1000.0
        dt = datetime.fromtimestamp(ts_num, tz=timezone.utc)
        return dt.strftime('%Y-%m-%dT%H:%M:%S')
    except (ValueError, OSError, OverflowError):
        pass

    # Return as-is (ISO 8601 or other string format)
    return ts_str


# ============== Value Formatting for Substitution ==============

def format_value_for_substitution(val):
    """Format a JSON value with ANSI colors for display in substituted messages."""
    if isinstance(val, bool):
        if val:
            return f"\033[1;32mtrue{RESET}"
        else:
            return f"\033[1;31mfalse{RESET}"
    elif val is None:
        return f"\033[1mnull{RESET}"
    elif isinstance(val, str):
        return f"\033[1;33m{val}{RESET}"
    elif isinstance(val, (int, float)):
        return f"\033[1;36m{val}{RESET}"
    elif isinstance(val, list):
        return format_array_for_subst(val)
    elif isinstance(val, dict):
        return format_object_for_subst(val)
    else:
        return f"\033[1;33m{val}{RESET}"


def format_array_for_subst(arr):
    """Format a JSON array with ANSI colors."""
    parts = [f"{DIM}[{RESET}"]
    for i, item in enumerate(arr):
        if i > 0:
            parts.append(f"{DIM}, {RESET}")
        parts.append(format_value_for_substitution(item))
    parts.append(f"{DIM}]{RESET}")
    return ''.join(parts)


def format_object_for_subst(obj):
    """Format a JSON object with ANSI colors (sorted keys)."""
    parts = [f"{DIM}{{{RESET}"]
    first = True
    for k in sorted(obj.keys()):
        if not first:
            parts.append(f"{DIM}, {RESET}")
        first = False
        parts.append(f"\033[35m{k}{RESET}")
        parts.append(f"{DIM}: {RESET}")
        parts.append(format_value_for_substitution(obj[k]))
    parts.append(f"{DIM}}}{RESET}")
    return ''.join(parts)


# ============== Placeholder Substitution ==============

def build_placeholder_regex(format_str):
    """Convert a placeholder format string to a regex.

    The format uses 'key' as the placeholder for the actual variable name.
    Examples:
    - '{key}' -> regex r'\{([^}]+?)\}'
    - '#{key}' -> regex r'#\{([^}]+?)\}'
    - '[[key]]' -> regex r'\[\[([^\]]+?)\]\]'
    """
    # Escape the format string but keep 'key' as a group
    # Split by 'key', escape each part, then join with capture group
    parts = format_str.split('key')
    escaped_parts = [re.escape(p) for p in parts]
    # Join with a non-greedy capture group
    pattern = r'(.+?)'.join(escaped_parts)
    return re.compile(pattern)


def substitute_message(message, context, placeholder_format='{key}'):
    """Substitute placeholders in message with values from context."""
    if context is None:
        return message

    try:
        regex = build_placeholder_regex(placeholder_format)
    except re.error:
        return message

    result = []
    last_end = 0

    for m in regex.finditer(message):
        result.append(message[last_end:m.start()])
        key = m.group(1)

        if isinstance(context, dict):
            if key in context:
                result.append(format_value_for_substitution(context[key]))
            else:
                # Missing key
                result.append(f"{DIM}{{{RESET}\033[1;31m{key}{RESET}{DIM}}}{RESET}")
        elif isinstance(context, list):
            try:
                idx = int(key)
                if 0 <= idx < len(context):
                    result.append(format_value_for_substitution(context[idx]))
                else:
                    result.append(f"{DIM}{{{RESET}\033[1;31m{key}{RESET}{DIM}}}{RESET}")
            except ValueError:
                result.append(f"{DIM}{{{RESET}\033[1;31m{key}{RESET}{DIM}}}{RESET}")

        last_end = m.end()

    result.append(message[last_end:])
    return ''.join(result)


# ============== JSON Flattening ==============

def flatten_json(data, prefix=''):
    """Flatten a JSON value into (path, value) pairs.

    - Objects: path uses ' > ' separator: 'a > b > c'
    - Arrays: path uses '[i]' suffix: 'arr[0]'
    - Combined: 'a[0] > b' for objects within arrays
    - Null values are excluded
    """
    result = []

    if isinstance(data, dict):
        for k in sorted(data.keys()):
            v = data[k]
            path = f"{prefix} > {k}" if prefix else k
            if isinstance(v, (dict, list)):
                result.extend(flatten_json(v, path))
            elif v is not None:
                result.append((path, v))
    elif isinstance(data, list):
        for i, v in enumerate(data):
            path = f"{prefix}[{i}]"
            if isinstance(v, (dict, list)):
                result.extend(flatten_json(v, path))
            elif v is not None:
                result.append((path, v))
    else:
        if data is not None:
            result.append((prefix, data))

    return result


def format_dump_value(val):
    """Format a value for dump-all display (plain text, no ANSI)."""
    if isinstance(val, bool):
        return 'true' if val else 'false'
    elif val is None:
        return ''
    elif isinstance(val, str):
        return val
    elif isinstance(val, float):
        # Check if it's actually an integer
        if val == int(val):
            return str(int(val))
        return str(val)
    else:
        return str(val)


