def load_config(config_file=None):
    """Load configuration from a TOML file."""
    config = {k: v for k, v in DEFAULT_CONFIG.items()}
    config['level_map'] = {}

    if tomllib is None:
        return config

    search_paths = []
    if config_file:
        search_paths = [config_file]
    else:
        # Standard user config locations
        if 'XDG_CONFIG_HOME' in os.environ:
            search_paths.append(os.path.join(os.environ['XDG_CONFIG_HOME'], 'fblog.toml'))
        if 'HOME' in os.environ:
            search_paths.append(os.path.join(os.environ['HOME'], '.config', 'fblog.toml'))

    for path in search_paths:
        if os.path.exists(path):
            try:
                with open(path, 'rb') as f:
                    user_config = tomllib.load(f)
                # Update config with user settings
                for k, v in user_config.items():
                    if k != 'level_map':
                        config[k] = v
                config['level_map'] = user_config.get('level_map', {})
                # Convert level_map keys to strings
                config['level_map'] = {str(k): str(v) for k, v in config['level_map'].items()}
                break
            except Exception as e:
                if config_file:
                    print(f"Warning: Could not load config file {path}: {e}", file=sys.stderr)

    return config


def find_value_by_keys(data, keys):
    """Find the first non-None value in data matching one of the keys."""
    for key in keys:
        if key in data:
            return data[key]
    return None


def get_nested_value(data, path_str):
    """Get a nested value from data using ' > ' separated path."""
    parts = [p.strip() for p in path_str.split(' > ')]
    current = data
    for part in parts:
        if not isinstance(current, dict) or part not in current:
            return None
        current = current[part]
    return current


