# ============== Template Engine ==============

def evaluate_expr(expr, context):
    """Evaluate a template expression.
    expr can be: variable_name, "string_literal", helper_name args...
    context is a dict mapping variable names to their string values.
    """
    expr = expr.strip()

    # Empty expression
    if not expr:
        return ''

    # String literal
    if expr.startswith('"') and expr.endswith('"') and len(expr) >= 2:
        return expr[1:-1]
    if expr.startswith("'") and expr.endswith("'") and len(expr) >= 2:
