        val = resolve_arg(*args[0], context)
        return f"\033[31m{val}{RESET}"

    elif helper == 'green':
        if not args:
            return ''
        val = resolve_arg(*args[0], context)
        return f"\033[32m{val}{RESET}"

    elif helper == 'blue':
        if not args:
            return ''
        val = resolve_arg(*args[0], context)
        return f"\033[34m{val}{RESET}"

    elif helper == 'yellow':
        if not args:
            return ''
        val = resolve_arg(*args[0], context)
        return f"\033[33m{val}{RESET}"

    elif helper == 'color_rgb':
        if len(args) < 4:
            return ''
        r = resolve_arg(*args[0], context)
        g = resolve_arg(*args[1], context)
        b = resolve_arg(*args[2], context)
        val = resolve_arg(*args[3], context)
        return f"\033[38;2;{r};{g};{b}m{val}{RESET}"

    elif helper == 'fixed_size':
        if len(args) < 2:
            return ''
        n_str = resolve_arg(*args[0], context)
        try:
            n = int(float(n_str))
        except (ValueError, TypeError):
            n = 0
        val = resolve_arg(*args[1], context)
        # Left-pad with spaces if shorter, truncate if longer
        if len(val) < n:
            return val.rjust(n)
        return val[:n]

    elif helper == 'min_size':
        if len(args) < 2:
            return ''
        n_str = resolve_arg(*args[0], context)
        try:
            n = int(float(n_str))
        except (ValueError, TypeError):
            n = 0
        val = resolve_arg(*args[1], context)
        # Left-pad with spaces if shorter
        if len(val) < n:
            return val.rjust(n)
        return val

    elif helper == 'uppercase':
        if not args:
            return ''
        val = resolve_arg(*args[0], context)
        return val.upper()

    elif helper == 'level_style':
        if not args:
            return ''
        val = resolve_arg(*args[0], context)
        return level_style(val)

    else:
        raise ValueError(f"Helper not found {helper}")


def render_template(template_str, context):
    """Render a Handlebars-like template with the given context."""
    result = []
    i = 0
    skip_depth = 0  # > 0 means we're in a false #if block

    while i < len(template_str):
        if template_str[i:i+2] == '{{':
            end = template_str.find('}}', i+2)
            if end == -1:
                # Unclosed - treat rest as text
                if skip_depth == 0:
                    result.append(template_str[i:])
                i = len(template_str)
                break

            inner = template_str[i+2:end].strip()

            if inner.startswith('#if '):
                var_name = inner[4:].strip()
                if skip_depth > 0:
                    skip_depth += 1
                else:
                    # Check if variable is truthy
                    val = context.get(var_name, '')
                    if not val:
                        skip_depth = 1
            elif inner == '/if':
                if skip_depth > 0:
                    skip_depth -= 1
            else:
                if skip_depth == 0:
                    try:
                        val = evaluate_expr(inner, context)
                        result.append(val)
                    except ValueError as e:
                        raise ValueError(str(e))

            i = end + 2
        else:
            if skip_depth == 0:
                result.append(template_str[i])
            i += 1

    return ''.join(result)


# ============== Timestamp Conversion ==============

def parse_timestamp(ts_val):
    """Convert a timestamp value to a displayable string.

    Handles:
    - ISO 8601 strings (returned as-is)
    - Unix timestamps in seconds (int/float)
    - Unix timestamps in milliseconds (int/float > 1e10)
    - String representations of numbers
    """
    if ts_val is None:
        return ''

    # Numeric timestamps
    if isinstance(ts_val, (int, float)) and not isinstance(ts_val, bool):
        ts_num = float(ts_val)
        if ts_num > 1e10:
            ts_num /= 1000.0
        try:
            dt = datetime.fromtimestamp(ts_num, tz=timezone.utc)
            return dt.strftime('%Y-%m-%dT%H:%M:%S')
        except (OSError, OverflowError, ValueError):
            return str(ts_val)

    ts_str = str(ts_val)

    # Try to parse as numeric string
    try:
        ts_num = float(ts_str)
        if ts_num > 1e10:
            ts_num /= 1000.0
        dt = datetime.fromtimestamp(ts_num, tz=timezone.utc)
        return dt.strftime('%Y-%m-%dT%H:%M:%S')
    except (ValueError, OSError, OverflowError):
        pass

    # Return as-is (ISO 8601 or other string format)
    return ts_str


# ============== Value Formatting for Substitution ==============

def format_value_for_substitution(val):
    """Format a JSON value with ANSI colors for display in substituted messages."""
    if isinstance(val, bool):
        if val:
            return f"\033[1;32mtrue{RESET}"
        else:
            return f"\033[1;31mfalse{RESET}"
    elif val is None:
        return f"\033[1mnull{RESET}"
    elif isinstance(val, str):
        return f"\033[1;33m{val}{RESET}"
    elif isinstance(val, (int, float)):
        return f"\033[1;36m{val}{RESET}"
    elif isinstance(val, list):
        return format_array_for_subst(val)
    elif isinstance(val, dict):
        return format_object_for_subst(val)
    else:
        return f"\033[1;33m{val}{RESET}"


def format_array_for_subst(arr):
    """Format a JSON array with ANSI colors."""
    parts = [f"{DIM}[{RESET}"]
    for i, item in enumerate(arr):
        if i > 0:
            parts.append(f"{DIM}, {RESET}")
        parts.append(format_value_for_substitution(item))
    parts.append(f"{DIM}]{RESET}")
    return ''.join(parts)


def format_object_for_subst(obj):
    """Format a JSON object with ANSI colors (sorted keys)."""
    parts = [f"{DIM}{{{RESET}"]
    first = True
    for k in sorted(obj.keys()):
        if not first:
            parts.append(f"{DIM}, {RESET}")
        first = False
        parts.append(f"\033[35m{k}{RESET}")
        parts.append(f"{DIM}: {RESET}")
        parts.append(format_value_for_substitution(obj[k]))
    parts.append(f"{DIM}}}{RESET}")
    return ''.join(parts)


# ============== Placeholder Substitution ==============

def build_placeholder_regex(format_str):
    """Convert a placeholder format string to a regex.

    The format uses 'key' as the placeholder for the actual variable name.
    Examples:
    - '{key}' -> regex r'\{([^}]+?)\}'
    - '#{key}' -> regex r'#\{([^}]+?)\}'
    - '[[key]]' -> regex r'\[\[([^\]]+?)\]\]'
    """
    # Escape the format string but keep 'key' as a group
    # Split by 'key', escape each part, then join with capture group
    parts = format_str.split('key')
    escaped_parts = [re.escape(p) for p in parts]
    # Join with a non-greedy capture group
    pattern = r'(.+?)'.join(escaped_parts)
    return re.compile(pattern)


def substitute_message(message, context, placeholder_format='{key}'):
    """Substitute placeholders in message with values from context."""
    if context is None:
        return message

    try:
        regex = build_placeholder_regex(placeholder_format)
    except re.error:
        return message

    result = []
    last_end = 0

    for m in regex.finditer(message):
        result.append(message[last_end:m.start()])
        key = m.group(1)

        if isinstance(context, dict):
            if key in context:
                result.append(format_value_for_substitution(context[key]))
            else:
                # Missing key
                result.append(f"{DIM}{{{RESET}\033[1;31m{key}{RESET}{DIM}}}{RESET}")
        elif isinstance(context, list):
            try:
                idx = int(key)
                if 0 <= idx < len(context):
                    result.append(format_value_for_substitution(context[idx]))
                else:
                    result.append(f"{DIM}{{{RESET}\033[1;31m{key}{RESET}{DIM}}}{RESET}")
            except ValueError:
                result.append(f"{DIM}{{{RESET}\033[1;31m{key}{RESET}{DIM}}}{RESET}")

        last_end = m.end()

    result.append(message[last_end:])
    return ''.join(result)


# ============== JSON Flattening ==============

def flatten_json(data, prefix=''):
    """Flatten a JSON value into (path, value) pairs.

    - Objects: path uses ' > ' separator: 'a > b > c'
    - Arrays: path uses '[i]' suffix: 'arr[0]'
    - Combined: 'a[0] > b' for objects within arrays
    - Null values are excluded
    """
    result = []

    if isinstance(data, dict):
        for k in sorted(data.keys()):
            v = data[k]
            path = f"{prefix} > {k}" if prefix else k
            if isinstance(v, (dict, list)):
                result.extend(flatten_json(v, path))
            elif v is not None:
                result.append((path, v))
    elif isinstance(data, list):
        for i, v in enumerate(data):
            path = f"{prefix}[{i}]"
            if isinstance(v, (dict, list)):
                result.extend(flatten_json(v, path))
            elif v is not None:
                result.append((path, v))
    else:
        if data is not None:
            result.append((prefix, data))

    return result


def format_dump_value(val):
    """Format a value for dump-all display (plain text, no ANSI)."""
    if isinstance(val, bool):
        return 'true' if val else 'false'
    elif val is None:
        return ''
    elif isinstance(val, str):
        return val
    elif isinstance(val, float):
        # Check if it's actually an integer
        if val == int(val):
            return str(int(val))
        return str(val)
    else:
        return str(val)


# ============== Lua Filter ==============

def json_key_to_lua(key):
    """Convert a JSON key to a valid Lua variable name."""
    # Replace any non-alphanumeric (except underscore) with underscore
    result = re.sub(r'[^a-zA-Z0-9_]', '_', key)
    # If starts with digit, prepend underscore
    if result and result[0].isdigit():
        result = '_' + result
    return result


def build_lua_vars(data):
    """Build a dict of Lua variable names to their Python values from JSON data."""
    result = {}

    if not isinstance(data, dict):
        return result

    for k, v in data.items():
        lua_key = json_key_to_lua(k)
        if isinstance(v, dict):
            result[lua_key] = v
        elif isinstance(v, list):
            result[lua_key] = v
        elif isinstance(v, bool):
            result[lua_key] = v
        elif v is None:
            result[lua_key] = None
        else:
            result[lua_key] = v

    return result


def format_lua_value(val):
    """Format a value as it would appear in --print-lua output."""
    if isinstance(val, bool):
        return 'true' if val else 'false'
    elif val is None:
        return 'nil'
    elif isinstance(val, str):
        return f'"{val}"'
    elif isinstance(val, float):
        if val == int(val):
            return str(int(val))
        return str(val)
    elif isinstance(val, int):
        return str(val)
    elif isinstance(val, list):
        items = ','.join(format_lua_value(v) for v in val)
        return '{' + items + '}'
    elif isinstance(val, dict):
        items = ', '.join(f"{k} = {format_lua_value(v)}" for k, v in val.items())
        return '{' + items + '}'
    else:
        return str(val)


def lua_to_python(expr):
    """Convert a Lua expression to Python."""
    result = expr

    # Replace Lua's ~= with Python's !=
    result = result.replace('~=', '!=')

    # Replace Lua nil with Python None
    result = re.sub(r'\bnil\b', 'None', result)

    # Replace Lua true/false with Python True/False
    result = re.sub(r'\btrue\b', 'True', result)
    result = re.sub(r'\bfalse\b', 'False', result)

    # Replace Lua string concatenation (..) with Python +
    # But be careful not to replace .. inside strings or numbers
    result = result.replace('..', ' + ')

    return result


def lua_pattern_to_python(pattern):
    """Convert a Lua pattern to a Python regex pattern."""
    result = []
    i = 0
    while i < len(pattern):
        c = pattern[i]
        if c == '%' and i+1 < len(pattern):
            nc = pattern[i+1]
            if nc == 'd': result.append(r'\d')
            elif nc == 'D': result.append(r'\D')
            elif nc == 'a': result.append('[a-zA-Z]')
            elif nc == 'A': result.append('[^a-zA-Z]')
            elif nc == 'w': result.append(r'\w')
            elif nc == 'W': result.append(r'\W')
            elif nc == 's': result.append(r'\s')
            elif nc == 'S': result.append(r'\S')
            elif nc == 'l': result.append('[a-z]')
            elif nc == 'L': result.append('[^a-z]')
            elif nc == 'u': result.append('[A-Z]')
            elif nc == 'U': result.append('[^A-Z]')
            elif nc == 'p': result.append(r'[!-/:-@\[-`{-~]')
            elif nc == 'c': result.append(r'[\x00-\x1f\x7f]')
            elif nc in r'\.^$()[]*+-?{}|%':
                result.append('\\' + nc)
            else:
                result.append(re.escape(nc))
            i += 2
        elif c == '-' and i > 0:
            # In Lua, '-' after a class/quantifier is non-greedy *?
            # But simple '-' in a character class is literal
            # This is tricky - for now treat as non-greedy repetition
            result.append('*?')
            i += 1
        elif c in r'\^$.|?*+()[]{':
            result.append('\\' + c)
            i += 1
        else:
            result.append(re.escape(c))
            i += 1

    return ''.join(result)


class StringLib:
    """Lua string library emulation."""

    @staticmethod
    def find(s, pattern, init=1, plain=False):
        if s is None:
            return None
        s = str(s)
        if plain:
            idx = s.find(pattern, init-1)
            if idx == -1:
                return None
            return (idx+1, idx+len(pattern))
        try:
            py_pattern = lua_pattern_to_python(str(pattern))
            m = re.search(py_pattern, s[init-1:])
            if m:
                return (m.start() + init, m.end() + init - 1)
            return None
        except re.error:
            return None

    @staticmethod
    def match(s, pattern, init=1):
        if s is None:
            return None
        s = str(s)
        try:
            py_pattern = lua_pattern_to_python(str(pattern))
            m = re.match(py_pattern, s[init-1:])
            if m:
                return m.group(0)
            return None
        except re.error:
            return None

    @staticmethod
    def gmatch(s, pattern):
        if s is None:
            return iter([])
        s = str(s)
        try:
            py_pattern = lua_pattern_to_python(str(pattern))
            return iter(re.findall(py_pattern, s))
        except re.error:
            return iter([])

    @staticmethod
    def gsub(s, pattern, repl, n=None):
        if s is None:
            return None
        s = str(s)
        try:
            py_pattern = lua_pattern_to_python(str(pattern))
            if n is not None:
                return re.sub(py_pattern, str(repl), s, count=n)
            return re.sub(py_pattern, str(repl), s)
        except re.error:
            return s

    @staticmethod
    def lower(s):
        if s is None:
            return None
        return str(s).lower()

    @staticmethod
    def upper(s):
        if s is None:
            return None
        return str(s).upper()

    @staticmethod
    def len(s):
        if s is None:
            return 0
        return len(str(s))

    @staticmethod
    def sub(s, i, j=None):
        if s is None:
            return ''
        s = str(s)
        if j is None:
            return s[i-1:]
        elif j < 0:
            return s[i-1:j]
        else:
            return s[i-1:j]

    @staticmethod
    def format(fmt, *args):
        # Very basic Lua string.format implementation
        result = fmt
        for arg in args:
            # Replace first format specifier
            result = re.sub(r'%[diouxXeEfgGsq]', str(arg), result, count=1)
        return result

    @staticmethod
    def rep(s, n, sep=''):
        if s is None:
            return ''
        return sep.join([str(s)] * n)

    @staticmethod
    def byte(s, i=1, j=None):
        if s is None:
            return None
        s = str(s)
        if not s:
            return None
        if j is None:
            return ord(s[i-1]) if 1 <= i <= len(s) else None
        return tuple(ord(s[k-1]) for k in range(i, min(j+1, len(s)+1)))

    @staticmethod
    def char(*args):
        return ''.join(chr(a) for a in args)


def evaluate_lua_filter(expr, lua_vars, print_lua=False):
    """Evaluate a Lua filter expression.

    Returns True if the entry passes the filter, False if not.
    Raises an exception if there's an error.
    """
    # Convert Lua expression to Python
    py_expr = lua_to_python(expr)

    # Build the evaluation environment
    safe_builtins = {
        'None': None,
        'True': True,
        'False': False,
        'str': str,
        'int': int,
        'float': float,
        'bool': bool,
        'len': len,
        'print': print,
        'type': type,
        'isinstance': isinstance,
    }

    eval_globals = {
        '__builtins__': safe_builtins,
        'string': StringLib(),
        'math': type('math', (), {
            'abs': abs,
            'floor': lambda x: int(x),
            'ceil': __import__('math').ceil,
            'sqrt': __import__('math').sqrt,
            'max': max,
            'min': min,
        })(),
        'table': type('table', (), {
            'insert': lambda t, v: t.append(v),
            'remove': lambda t, i=None: t.pop(i-1 if i else -1),
            'concat': lambda t, sep='': sep.join(str(x) for x in t),
        })(),
        'pairs': lambda t: iter(t.items()) if isinstance(t, dict) else iter(enumerate(t)),
        'ipairs': lambda t: iter(enumerate(t, 1)),
        'tostring': str,
        'tonumber': lambda x, base=10: int(x, base) if isinstance(x, str) and base != 10 else float(x),
        'type': lambda x: (
            'string' if isinstance(x, str) else
            'number' if isinstance(x, (int, float)) and not isinstance(x, bool) else
            'boolean' if isinstance(x, bool) else
            'nil' if x is None else
            'table' if isinstance(x, (dict, list)) else
            'userdata'
        ),
        'pcall': lambda f, *a: (True, f(*a)),
    }

    # Add the JSON variables
    eval_globals.update(lua_vars)

    try:
        result = eval(py_expr, eval_globals, {})
        return bool(result)
    except SyntaxError as e:
        raise SyntaxError(f"SyntaxError {{ message: \"src/filter.rs:23:1: {e.msg}\", incomplete_input: false }}")
    except Exception as e:
        raise RuntimeError(f"RuntimeError(\"{str(e)}\")")


# ============== Configuration ==============

DEFAULT_CONFIG = {
    'message_keys': ['short_message', 'msg', 'message'],
    'time_keys': ['timestamp', 'time', '@timestamp'],
    'level_keys': ['level', 'severity', 'log.level', 'loglevel'],
    'dump_all_exclude': [],
    'always_print_fields': [],
    'main_line_format': (
        '{{bold(fixed_size 19 fblog_timestamp)}} '
        '{{level_style (uppercase (fixed_size 5 fblog_level))}}:'
        '{{#if fblog_prefix}} {{bold(cyan fblog_prefix)}}{{/if}} '
        '{{fblog_message}}'
    ),
    'additional_value_format': '{{bold (color_rgb 150 150 150 (min_size 25 key))}}: {{value}}',
    'level_map': {},
}


def load_config(config_file=None):
    """Load configuration from a TOML file."""
    config = {k: v for k, v in DEFAULT_CONFIG.items()}
    config['level_map'] = {}

    if tomllib is None:
        return config

    search_paths = []
    if config_file:
        search_paths = [config_file]
    else:
        # Standard user config locations
        if 'XDG_CONFIG_HOME' in os.environ:
            search_paths.append(os.path.join(os.environ['XDG_CONFIG_HOME'], 'fblog.toml'))
        if 'HOME' in os.environ:
            search_paths.append(os.path.join(os.environ['HOME'], '.config', 'fblog.toml'))

    for path in search_paths:
        if os.path.exists(path):
            try:
                with open(path, 'rb') as f:
                    user_config = tomllib.load(f)
                # Update config with user settings
                for k, v in user_config.items():
                    if k != 'level_map':
                        config[k] = v
                config['level_map'] = user_config.get('level_map', {})
                # Convert level_map keys to strings
                config['level_map'] = {str(k): str(v) for k, v in config['level_map'].items()}
                break
            except Exception as e:
                if config_file:
                    print(f"Warning: Could not load config file {path}: {e}", file=sys.stderr)

    return config


def find_value_by_keys(data, keys):
    """Find the first non-None value in data matching one of the keys."""
    for key in keys:
        if key in data:
            return data[key]
    return None


def get_nested_value(data, path_str):
    """Get a nested value from data using ' > ' separated path."""
    parts = [p.strip() for p in path_str.split(' > ')]
    current = data
    for part in parts:
        if not isinstance(current, dict) or part not in current:
            return None
        current = current[part]
    return current


# ============== Main Processing ==============

def process_json_entry(data, config, args, prefix_text='', filter_expr=None):
    """Process a parsed JSON log entry.

    Returns:
    - ('ok', main_line, [additional_lines]) - success
    - ('filtered', None, []) - filtered out
    - ('filter_error', error_msg, []) - filter error
    - ('render_error', error_msg, []) - template render error
    """
    level_map = config.get('level_map', {})
    message_keys = config.get('message_keys', DEFAULT_CONFIG['message_keys'])
    time_keys = config.get('time_keys', DEFAULT_CONFIG['time_keys'])
    level_keys = config.get('level_keys', DEFAULT_CONFIG['level_keys'])

    # Find message
    msg_val = find_value_by_keys(data, message_keys)
    message = str(msg_val) if msg_val is not None else ''

    # Find timestamp
    time_val = find_value_by_keys(data, time_keys)
    timestamp = parse_timestamp(time_val) if time_val is not None else ''

    # Find level
    level_val = find_value_by_keys(data, level_keys)
    level_str = str(level_val) if level_val is not None else ''

    # Apply level mapping
    level_lower = level_str.lower()
    for map_from, map_to in level_map.items():
        if str(map_from).lower() == level_lower:
            level_str = map_to
            break

    # Build Lua variables for filter
    lua_vars = build_lua_vars(data)

    # Apply Lua filter
    if filter_expr is not None:
        if args.print_lua:
            for k in sorted(lua_vars.keys()):
                v = lua_vars[k]
                print(f"{k} = {format_lua_value(v)}")

        try:
            passed = evaluate_lua_filter(filter_expr, lua_vars)
            if not passed:
                return ('filtered', None, [])
        except SyntaxError as e:
            return ('filter_error', str(e), [])
        except RuntimeError as e:
            return ('filter_error', str(e), [])
        except Exception as e:
            return ('filter_error', str(e), [])

    # Apply placeholder substitution
    if getattr(args, 'substitute', False):
        ctx_key = getattr(args, 'context_key', None) or 'context'
        placeholder_fmt = getattr(args, 'placeholder_format', None) or '{key}'
        context_val = data.get(ctx_key)
        if context_val is not None:
            message = substitute_message(message, context_val, placeholder_fmt)

    # Build template context
    template_context = {
        'fblog_message': message,
        'fblog_timestamp': timestamp,
        'fblog_level': level_str,
        'fblog_prefix': prefix_text,
    }

    # Add all JSON fields (flattened scalars only for simple template access)
    for k, v in data.items():
        if isinstance(v, (dict, list)):
            template_context[k] = json.dumps(v)
        elif isinstance(v, bool):
            template_context[k] = 'true' if v else 'false'
        elif v is None:
            template_context[k] = ''
        else:
            template_context[k] = str(v)

    # Render main line
    main_fmt = config.get('main_line_format', DEFAULT_CONFIG['main_line_format'])
    try:
        main_line = render_template(main_fmt, template_context)
    except ValueError as e:
        return ('render_error', str(e), [])

    additional_lines = []
    additional_value_fmt = config.get('additional_value_format', DEFAULT_CONFIG['additional_value_format'])

    # Always-print fields
    always_fields = config.get('always_print_fields', [])
    for field in always_fields:
        val = data.get(field)
        if val is not None:
            fmt_val = format_dump_value(val)
            add_ctx = {'key': field, 'value': fmt_val}
            try:
                line = render_template(additional_value_fmt, add_ctx)
                additional_lines.append(line)
            except Exception:
                pass

    # Additional values (-a flag)
    additional_values = getattr(args, 'additional_value', []) or []
    for path in additional_values:
        val = get_nested_value(data, path)
        if val is not None:
            fmt_val = format_dump_value(val)
            add_ctx = {'key': path, 'value': fmt_val}
            try:
                line = render_template(additional_value_fmt, add_ctx)
                additional_lines.append(line)
            except Exception:
                pass

    # Dump all values
    dump_all = getattr(args, 'dump_all', False)
    excluded = set(getattr(args, 'excluded_value', []) or [])
    dump_all_exclude = set(config.get('dump_all_exclude', []))

    if dump_all:
        flat = flatten_json(data)
        for path, val in flat:
            # Skip excluded and always-print fields (already shown)
            if path in excluded:
                continue
            if path in dump_all_exclude:
                continue

            fmt_val = format_dump_value(val)
            add_ctx = {'key': path, 'value': fmt_val}
            try:
                line = render_template(additional_value_fmt, add_ctx)
                additional_lines.append(line)
            except Exception:
                pass

    return ('ok', main_line, additional_lines)


def process_line(line, config, args, filter_expr):
    """Process a single input line and return output lines."""
    # Strip newline
    line_stripped = line.rstrip('\n').rstrip('\r')

    prefix_text = ''
    json_str = line_stripped

    # Handle prefix mode
    if getattr(args, 'with_prefix', False):
        brace_idx = line_stripped.find('{')
        if brace_idx > 0:
            raw_prefix = line_stripped[:brace_idx]
            # Strip trailing separator (like " | ")
            prefix_text = raw_prefix.rstrip()
            if prefix_text.endswith('|'):
                prefix_text = prefix_text[:-1].rstrip()
            json_str = line_stripped[brace_idx:]
        elif brace_idx == -1:
            return [f"\033[1;38;2;255;135;22m??? >{RESET} {line_stripped}"]
        # If brace_idx == 0, no prefix, process normally

    # Try to parse as JSON
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return [f"\033[1;38;2;255;135;22m??? >{RESET} {line_stripped}"]

    # Must be a JSON object
    if not isinstance(data, dict):
        return [f"\033[1;38;2;255;135;22m??? >{RESET} {line_stripped}"]

    result_type, main_line, additional_lines = process_json_entry(
        data, config, args, prefix_text, filter_expr
    )

    if result_type == 'filtered':
        return []
    elif result_type == 'filter_error':
        return [f"\033[31mFailed to apply filter expression{RESET}: '{main_line}'"]
    elif result_type == 'render_error':
        return [f"\033[1;31m??? >{RESET} Failed to process line: Error rendering \"main_line\" line 1, col 1: {main_line}"]
    else:
        return [main_line] + additional_lines


def validate_filter(filter_expr, no_implicit_return):
    """Validate a filter expression for syntax errors.
    Returns error message string if invalid, None if valid.
    """
    # We'll validate by trying to compile it
    py_expr = lua_to_python(filter_expr)
    try:
        compile(py_expr, '<filter>', 'eval')
        return None
    except SyntaxError as e:
        return f"SyntaxError {{ message: \"src/filter.rs:23:1: {e.msg} near '{e.text}'\", incomplete_input: false }}"


def main():
    parser = argparse.ArgumentParser(
        prog='fblog',
        description='json log viewer',
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )

    parser.add_argument(
        'input', nargs='?', default='-', metavar='INPUT',
        help='Sets the input file to use, otherwise assumes stdin [default: -]'
    )
    parser.add_argument(
        '-a', '--additional-value', action='append', metavar='additional-value',
        dest='additional_value',
        help='adds additional values'
    )
    parser.add_argument(
        '--config-file', metavar='config-file', dest='config_file',
        help='configuration file to load'
    )
    parser.add_argument(
        '-m', '--message-key', action='append', metavar='message-key',
        dest='message_key',
        help='Adds an additional key to detect the message in the log entry. '
             'The first matching key will be assigned to `fblog_message`.'
    )
    parser.add_argument(
        '--print-lua', action='store_true', dest='print_lua',
        help='Prints lua init expressions. Used for fblog debugging.'
    )
    parser.add_argument(
        '-t', '--time-key', action='append', metavar='time-key',
        dest='time_key',
        help='Adds an additional key to detect the time in the log entry. '
             'The first matching key will be assigned to `fblog_timestamp`.'
    )
    parser.add_argument(
        '-l', '--level-key', action='append', metavar='level-key',
        dest='level_key',
        help='Adds an additional key to detect the level in the log entry. '
             'The first matching key will be assigned to `fblog_level`.'
    )
    parser.add_argument(
        '--map-level', action='append', metavar='from=to',
        dest='map_level',
        help='Rewrite the log level from one value to another.'
    )
    parser.add_argument(
        '-d', '--dump-all', action='store_true', dest='dump_all',
        help='dumps all values'
    )
    parser.add_argument(
        '-x', '--excluded-value', action='append', metavar='excluded-value',
        dest='excluded_value',
        help='Excludes values (--dump-all is enabled implicitly)'
    )
    parser.add_argument(
        '-p', '--with-prefix', action='store_true', dest='with_prefix',
        help='consider all text before opening curly brace as prefix'
    )
    parser.add_argument(
        '-f', '--filter', metavar='filter', dest='filter',
        help='lua expression to filter log entries. '
             '`message ~= nil and string.find(message, "text.*") ~= nil`'
    )
    parser.add_argument(
        '--no-implicit-filter-return-statement', action='store_true',
        dest='no_implicit_filter_return',
        help="if you pass a filter expression 'return' is automatically prepended. "
             "Pass this switch to disable the implicit return."
    )
    parser.add_argument(
        '--main-line-format', metavar='main-line-format', dest='main_line_format',
        help='Formats the main fblog output. All log values can be used. '
             'fblog provides sanitized variables starting with `fblog_`.'
    )
    parser.add_argument(
        '--additional-value-format', metavar='additional-value-format',
        dest='additional_value_format',
        help='Formats the additional value fblog output.'
    )
    parser.add_argument(
        '-s', '--substitute', action='store_true', dest='substitute',
        help='Enable substitution of placeholders in the log messages with their '
             'corresponding values from the context.'
    )
    parser.add_argument(
        '-c', '--context-key', metavar='context-key', dest='context_key',
        help='Use this key as the source of substitutions for the message. '
             'Value can either be an array ({1}) or an object ({key}).'
    )
    parser.add_argument(
        '-F', '--placeholder-format', metavar='placeholder-format',
        dest='placeholder_format',
        help='The format that should be used for substituting values in the message, '
             'where the key is the literal word `key`. Example: [[key]] or ${key}.'
    )
    parser.add_argument(
        '-V', '--version', action='version', version=f'fblog {VERSION}'
    )

    args = parser.parse_args()

    # Implicitly enable dump_all if excluded values are specified
    if args.excluded_value:
        args.dump_all = True

    # Load configuration
    config = load_config(args.config_file)

    # Apply CLI overrides
    if args.message_key:
        config['message_keys'] = args.message_key + config.get('message_keys', DEFAULT_CONFIG['message_keys'])

    if args.time_key:
        config['time_keys'] = args.time_key + config.get('time_keys', DEFAULT_CONFIG['time_keys'])

    if args.level_key:
        config['level_keys'] = args.level_key + config.get('level_keys', DEFAULT_CONFIG['level_keys'])

    if args.map_level:
        for mapping in args.map_level:
            parts = mapping.split('=', 1)
            if len(parts) == 2:
                from_val = parts[0].strip()
                to_val = parts[1].strip()
                config['level_map'][from_val.lower()] = to_val

    if args.main_line_format:
        config['main_line_format'] = args.main_line_format

    if args.additional_value_format:
        config['additional_value_format'] = args.additional_value_format

    # Prepare filter expression
    filter_expr = None
    if args.filter:
        filter_str = args.filter
        # Validate syntax first
        py_expr = lua_to_python(filter_str)
        try:
            compile(py_expr, '<filter>', 'eval')
        except SyntaxError as e:
            near = e.text.strip() if e.text else ''
            # Find what's near the error
            print(f"\033[31mFailed to apply filter expression{RESET}: 'SyntaxError {{ message: \"src/filter.rs:23:1: unexpected symbol near '{near}'\", incomplete_input: false }}'")
            sys.exit(0)
        filter_expr = filter_str

    # Open input
    if args.input == '-':
        input_stream = sys.stdin
        close_stream = False
    else:
        try:
            input_stream = open(args.input, 'r', encoding='utf-8', errors='strict')
            close_stream = True
        except FileNotFoundError:
            print(f"Error: file not found: {args.input}", file=sys.stderr)
            sys.exit(1)
        except Exception as e:
            print(f"Error: {e}", file=sys.stderr)
            sys.exit(1)

    # Process input
    try:
        line_buf = ''
        raw_file = None

        if args.input != '-':
            # Open as binary to handle UTF-8 errors line by line
            raw_file = open(args.input, 'rb')
            if close_stream:
                input_stream.close()
                close_stream = False
        else:
            raw_file = sys.stdin.buffer

        while True:
            try:
                raw_line = raw_file.readline()
                if not raw_line:
                    break

                try:
                    line = raw_line.decode('utf-8')
                except UnicodeDecodeError:
                    print(f"\033[1;31m??? >{RESET} Could not read line: stream did not contain valid UTF-8")
                    continue

                output_lines = process_line(line, config, args, filter_expr)
                for out_line in output_lines:
                    print(out_line)

            except BrokenPipeError:
                break

    except KeyboardInterrupt:
        pass
    finally:
        if close_stream and input_stream != sys.stdin:
            input_stream.close()
        if raw_file and raw_file != sys.stdin.buffer:
            try:
                raw_file.close()
            except:
                pass


